"use strict";(self.webpackChunkmedical_prescription_for_woocommerce_docs=self.webpackChunkmedical_prescription_for_woocommerce_docs||[]).push([[6959],{8696(e,o,t){t.r(o),t.d(o,{comp:()=>n,data:()=>i});var a=t(641);const r={},n=(0,t(6262).A)(r,[["render",function(e,o){const t=(0,a.g2)("RouteLink");return(0,a.uX)(),(0,a.CE)("div",null,[o[5]||(o[5]=(0,a.Fv)('<h1 id="about" tabindex="-1"><a class="header-anchor" href="#about"><span>About</span></a></h1><p>This site is the official user documentation for the <strong>Medical Prescription Attachment for WooCommerce</strong> plugin, published and maintained by Webkul Software.</p><h2 id="about-the-plugin" tabindex="-1"><a class="header-anchor" href="#about-the-plugin"><span>About the plugin</span></a></h2><p>Medical Prescription Attachment for WooCommerce is a WordPress plugin that turns a standard WooCommerce store into a compliant online pharmacy. It lets a store owner mark individual products, or whole categories, as requiring a doctor&#39;s prescription. Customers buying those products must attach a prescription file before checkout will complete; the order is then held until a store administrator has reviewed the upload and approved or rejected it.</p><p>Around that core gate the plugin adds the workflow a real pharmacy needs: configurable upload rules (file formats, file counts, multiple uploads), an <em>Attach Later</em> flow for logged-in customers who do not have the document to hand, a re-upload path after a rejection, four prescription statuses with an order-note audit trail, and three WooCommerce emails that keep the administrator and the customer informed. Version 1.3.x adds optional OCR and AI reading of uploaded prescriptions — including a Google Gemini Vision fallback for handwriting — plus a customer-facing prescription vault, a chronic-disease pill organizer, and a frontend prescription search.</p><p>The plugin is sold on <a href="https://codecanyon.net/item/medical-prescription-attachment-plugin-for-woocommerce/24649311" target="_blank" rel="noopener noreferrer">CodeCanyon</a> and a working <a href="https://medical-prescription-for-woocommerce.wcdemo.webkul.com/" target="_blank" rel="noopener noreferrer">live demo</a> is available, stocked with prescription-gated medicines alongside freely purchasable items so both paths can be tried.</p><h2 id="about-webkul" tabindex="-1"><a class="header-anchor" href="#about-webkul"><span>About Webkul</span></a></h2><p>Webkul Software is an eCommerce software company founded in <strong>2010</strong> by Vipin Sahu, Vinay Yadav, and Prakash Sahu, headquartered in <strong>Noida, Uttar Pradesh, India</strong>. Webkul builds B2B and B2C eCommerce, marketplace, hyperlocal, and mobile application products, and develops extensions for platforms including WooCommerce, Magento, Shopify, Odoo, Bagisto, and UnoPim.</p><p>Webkul is a CodeCanyon Featured Author at Author Level 10 and contributes to WooCommerce core. Company details, the full product catalogue, and corporate information are published at <a href="https://webkul.com/" target="_blank" rel="noopener noreferrer">webkul.com</a>.</p><h2 id="about-this-documentation" tabindex="-1"><a class="header-anchor" href="#about-this-documentation"><span>About this documentation</span></a></h2><p>These guides cover installation, configuration, the customer experience, and the store owner&#39;s review workflow. They are written for pharmacy and healthcare store operators setting the plugin up, and for developers integrating it into an existing WooCommerce site.</p><p><strong>These pages document software behaviour only.</strong> They are not medical, pharmaceutical, or legal advice. Deciding which medicines may be sold online, what constitutes a valid prescription, who may verify one, and how long records must be kept is governed by the law of your jurisdiction and remains the responsibility of the store operator.</p><p>The documentation is a static site. Every page is also published as raw markdown for AI agents and automated tools — append <code>.md</code> to any page URL, or start from <a href="https://wpdoc.webkul.com/medical-prescription/llms.txt" target="_blank" rel="noopener noreferrer">llms.txt</a>.</p>',13)),(0,a.Lk)("p",null,[o[2]||(o[2]=(0,a.eW)("For questions about the plugin, see ",-1)),(0,a.bF)(t,{to:"/contact.html"},{default:(0,a.k6)(()=>[...o[0]||(o[0]=[(0,a.eW)("Contact",-1)])]),_:1}),o[3]||(o[3]=(0,a.eW)(". For how this site handles data, see ",-1)),(0,a.bF)(t,{to:"/privacy.html"},{default:(0,a.k6)(()=>[...o[1]||(o[1]=[(0,a.eW)("Privacy",-1)])]),_:1}),o[4]||(o[4]=(0,a.eW)(".",-1))])])}]]),i=JSON.parse('{"path":"/about.html","title":"About","lang":"en-US","frontmatter":{"title":"About","description":"Webkul, founded 2010 in Noida India, publishes the Medical Prescription Attachment for WooCommerce plugin. About the plugin, the company, and these docs.","sidebar":false},"headers":[{"level":2,"title":"About the plugin","slug":"about-the-plugin","link":"#about-the-plugin","children":[]},{"level":2,"title":"About Webkul","slug":"about-webkul","link":"#about-webkul","children":[]},{"level":2,"title":"About this documentation","slug":"about-this-documentation","link":"#about-this-documentation","children":[]}],"git":{},"filePathRelative":"about.md"}')}}]);